instruction:
Convert this MySQL table definition to PostgreSQL:

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(255) NOT NULL
);

output:
CREATE TABLE users (
  id SERIAL PRIMARY KEY,
  email VARCHAR(255) NOT NULL
);

instruction:
Convert this MySQL aggregation to PostgreSQL:

SELECT user_id, GROUP_CONCAT(item ORDER BY item SEPARATOR ", ") AS items
FROM cart_items GROUP BY user_id;

Convert this PostgreSQL insert to MySQL (no RETURNING clause):

INSERT INTO accounts (name) VALUES ('ada')
RETURNING id;

Convert this SQL Server query to PostgreSQL:

SELECT GETDATE() AS now_utc, DATEDIFF(day, started, GETDATE()) AS age_days
FROM jobs;

Convert this SQLite timestamp query to PostgreSQL:

SELECT id, strftime('%Y-%m-%d', created) AS day
FROM events;

Convert this Oracle pagination to PostgreSQL:

SELECT * FROM (
  SELECT * FROM products ORDER BY price
) WHERE ROWNUM <= 5;

Convert this PostgreSQL upsert to MySQL:

INSERT INTO settings (key, value) VALUES ('theme', 'dark')
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

Convert this PostgreSQL unnest query to MySQL 8:

SELECT u.name, t
FROM users u, unnest(u.tags) AS t;

output:
SELECT u.name, jt.t
FROM users u
JOIN JSON_TABLE(u.tags, '$[*]' COLUMNS (t VARCHAR(50) PATH '$')) AS jt;

instruction:
Convert this MySQL date extraction to SQL Server:

SELECT EXTRACT(YEAR FROM ordered_at) AS yr, COUNT(*) AS n
FROM orders GROUP BY EXTRACT(YEAR FROM ordered_at);

Convert this PostgreSQL DISTINCT ON query to SQL Server:

SELECT DISTINCT ON (user_id) user_id, created_at, amount
FROM payments ORDER BY user_id, created_at DESC;

output:
SELECT user_id, created_at, amount FROM (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY created_at DESC) AS rn
  FROM payments
) t WHERE rn = 1;

